      --blue-2: #1d4ed8;
      --navy: #0d1421;
      --text: #111827;
      --muted: #808a9d;
      --border: #e6eaf0;
      --bg: #f7f9fc;
      --panel: #ffffff;
      --green: #16c784;
      --red: #ea3943;
      --amber: #f59e0b;
      --shadow: 0 12px 34px rgba(13, 20, 33, .07);
      --mono: "SFMono-Regular", "Roboto Mono", "Cascadia Mono", Consolas, monospace;
      --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }
    * { box-sizing: border-box; }
    body { margin: 0; background: var(--bg); color: var(--navy); font-family: var(--sans); font-size: 14px; }
