    .up { color: var(--green); font-weight: 700; }
    .down { color: var(--red); font-weight: 700; }
    .neutral { color: var(--amber); font-weight: 700; }
    .navbar { position: sticky; top: 0; z-index: 30; display: flex; align-items: center; gap: 24px; height: 64px; padding: 0 24px; background: rgba(255,255,255,.96); border-bottom: 1px solid var(--border); backdrop-filter: blur(12px); }
    .brand { display: flex; align-items: center; gap: 10px; font-size: 19px; font-weight: 850; letter-spacing: -.03em; }
    .logo { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; color: #fff; background: linear-gradient(135deg, var(--blue), #6d8dff); box-shadow: 0 8px 18px rgba(56,97,251,.24); }
    .navlinks { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; }
    .nav-item { padding: 10px 11px; border-radius: 10px; color: #374151; font-weight: 650; position: relative; }
