    .actions { display: flex; align-items: center; gap: 10px; }
    .search { width: min(320px, 23vw); height: 38px; border: 1px solid var(--border); border-radius: 11px; padding: 0 12px 0 34px; background: #f8fafc; color: #111827; outline: none; }
    .search-wrap { position: relative; }
    .search-wrap span { position: absolute; left: 12px; top: 9px; color: var(--muted); }
    .btn { border: 1px solid var(--border); background: #fff; color: var(--navy); border-radius: 10px; height: 38px; padding: 0 13px; font-weight: 750; cursor: pointer; display: inline-flex; align-items: center; gap: 7px; }
    .btn:hover { border-color: #cfd7e4; background: #f8fafc; }
    .btn.primary { background: var(--blue); border-color: var(--blue); color: #fff; box-shadow: 0 10px 22px rgba(56,97,251,.22); }
    .page { max-width: 1800px; margin: 0 auto; padding: 16px 20px 42px; }
    .promo { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 14px; min-height: 54px; padding: 12px 16px; border: 1px solid #d9e2ff; border-radius: 16px; background: linear-gradient(100deg, #f7f9ff, #edf3ff 52%, #f9fbff); box-shadow: var(--shadow); overflow: hidden; }
    .promo-main { display: flex; align-items: center; gap: 12px; min-width: 0; }
    .badge { display: inline-flex; align-items: center; height: 24px; padding: 0 9px; border-radius: 999px; background: #e8efff; color: var(--blue); font-size: 12px; font-weight: 800; }
    .promo-text { font-weight: 800; letter-spacing: -.01em; }
    .promo-sub { color: var(--muted); margin-left: 6px; }
    .promo-controls { display: flex; align-items: center; gap: 8px; }
    .icon-btn { width: 32px; height: 32px; display: grid; place-items: center; border-radius: 9px; border: 1px solid #d7e1ff; background: #fff; color: var(--blue); cursor: pointer; }
    .hero { display: grid; grid-template-columns: minmax(280px, 1.15fr) minmax(420px, 1.85fr); gap: 16px; margin-top: 16px; }
