    h1 { margin: 0 0 9px; font-size: clamp(26px, 3vw, 42px); letter-spacing: -.055em; line-height: 1.02; }
    .lede { margin: 0; color: #526071; font-size: 15px; line-height: 1.55; max-width: 760px; }
    .metrics { display: grid; grid-template-columns: repeat(4, minmax(120px, 1fr)); gap: 12px; }
    .metric-card { background: var(--panel); border: 1px solid var(--border); border-radius: 16px; padding: 15px; box-shadow: var(--shadow); min-width: 0; }
    .metric-label { color: var(--muted); font-size: 12px; font-weight: 750; text-transform: uppercase; letter-spacing: .04em; }
    .metric-value { margin-top: 8px; font-size: 24px; line-height: 1; font-weight: 850; letter-spacing: -.035em; font-variant-numeric: tabular-nums; }
    .metric-change { margin-top: 9px; font-size: 12px; color: #526071; }
    .ai-bar { margin-top: 16px; display: flex; align-items: center; gap: 12px; padding: 12px; background: #111827; color: #fff; border-radius: 16px; overflow-x: auto; box-shadow: 0 16px 32px rgba(13,20,33,.14); }
    .ai-prompt { flex: 0 0 auto; display: flex; align-items: center; gap: 8px; font-weight: 800; }
    .ai-chip { flex: 0 0 auto; border: 1px solid rgba(255,255,255,.16); background: rgba(255,255,255,.08); color: #e5e7eb; border-radius: 999px; padding: 8px 10px; font-size: 12px; cursor: pointer; }
    .tab-shell { margin-top: 16px; background: var(--panel); border: 1px solid var(--border); border-radius: 18px; box-shadow: var(--shadow); overflow: hidden; }
    .tabs-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; border-bottom: 1px solid var(--border); }
    .tabs { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 1px; }
    .tab { flex: 0 0 auto; border: 1px solid transparent; background: transparent; color: #4b5563; border-radius: 999px; padding: 8px 13px; cursor: pointer; font-weight: 800; }
    .tab.active { background: #eef3ff; border-color: #dce5ff; color: var(--blue); }
    .index-card { display: grid; grid-template-columns: minmax(220px, 1fr) repeat(4, minmax(82px, auto)); gap: 14px; align-items: center; margin: 16px; padding: 13px 15px; border: 1px solid #dde6f4; border-radius: 14px; background: linear-gradient(180deg, #fbfdff, #f7faff); }
    .index-name { font-weight: 850; }
    .index-name span { color: var(--muted); font-weight: 700; margin-left: 6px; }
    .index-cell { text-align: right; font-family: var(--mono); font-size: 13px; font-variant-numeric: tabular-nums; }
    .table-toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding: 0 16px 14px; }
    .toolbar-left, .toolbar-right { display: flex; flex-wrap: wrap; align-items: center; gap: 9px; }
    .selectish { height: 38px; padding: 0 12px; border: 1px solid var(--border); border-radius: 10px; background: #fff; font-weight: 800; color: #374151; }
    .panel { display: none; margin: 0 16px 14px; border: 1px solid #dfe7f2; border-radius: 14px; background: #fbfdff; padding: 14px; }
    .panel.open { display: block; }
    .panel-grid { display: grid; grid-template-columns: repeat(5, minmax(130px, 1fr)); gap: 12px; }
    label.check, .filter-field label { display: flex; gap: 8px; align-items: center; color: #374151; font-weight: 750; }
    .filter-field { display: grid; gap: 6px; }
    .filter-field input, .filter-field select { height: 36px; border: 1px solid var(--border); border-radius: 10px; padding: 0 10px; background: #fff; }
    .table-wrap { overflow-x: auto; border-top: 1px solid var(--border); }
    table { width: 100%; border-collapse: separate; border-spacing: 0; min-width: 1180px; }
    thead th { position: sticky; top: 64px; z-index: 12; background: #fff; border-bottom: 1px solid var(--border); color: #687386; font-size: 12px; padding: 11px 10px; text-align: right; font-weight: 850; white-space: nowrap; cursor: pointer; }
    thead th:first-child, thead th:nth-child(2) { text-align: left; }
    tbody td { border-bottom: 1px solid #eef1f6; padding: 12px 10px; text-align: right; white-space: nowrap; font-family: var(--mono); font-size: 13px; font-variant-numeric: tabular-nums; }
    tbody td:first-child { text-align: left; color: #6b7280; font-family: var(--sans); font-weight: 750; }
    tbody td:nth-child(2) { text-align: left; font-family: var(--sans); }
    tbody tr { background: #fff; }
    tbody tr:hover { background: #f8fbff; }
    .coin { display: flex; align-items: center; gap: 10px; min-width: 230px; }
    .coin-icon { width: 30px; height: 30px; border-radius: 999px; display: grid; place-items: center; color: #fff; font-size: 12px; font-weight: 900; box-shadow: inset 0 0 0 1px rgba(255,255,255,.35); }
    .coin-name { font-weight: 850; color: var(--navy); }
    .coin-symbol { margin-left: 5px; color: var(--muted); font-weight: 750; }
    .watch { color: #cbd5e1; font-size: 16px; margin-right: 5px; cursor: pointer; }
    .watch.active { color: #fbbf24; }
    .spark { width: 118px; height: 34px; display: inline-block; }
    .spark path { fill: none; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
    .spark-fill { opacity: .09; stroke: none; }
    .hidden-col { display: none !important; }
    .pagination { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding: 15px 16px; color: #5f6b7a; }
    .pages { display: flex; align-items: center; gap: 6px; }
    .page-btn { border: 1px solid var(--border); background: #fff; min-width: 34px; height: 34px; border-radius: 9px; cursor: pointer; font-weight: 800; color: #526071; }
    .page-btn.active { background: var(--blue); border-color: var(--blue); color: #fff; }
    .summary, .info-content { margin-top: 16px; background: var(--panel); border: 1px solid var(--border); border-radius: 18px; padding: 20px; box-shadow: var(--shadow); }
    .summary h2, .info-content h2 { margin: 0 0 10px; font-size: 22px; letter-spacing: -.03em; }
    .summary p, .info-content p { color: #526071; line-height: 1.65; margin: 0; }
    .more-summary { display: none; margin-top: 12px !important; }
    .more-summary.open { display: block; }
    .read-more { margin-top: 13px; color: var(--blue); background: transparent; border: 0; padding: 0; font-weight: 850; cursor: pointer; }
    .info-grid { display: grid; grid-template-columns: repeat(2, minmax(260px, 1fr)); gap: 18px; margin-top: 12px; }
    .info-block { border-top: 1px solid var(--border); padding-top: 15px; }
    .info-block h3 { margin: 0 0 8px; font-size: 16px; }
    footer { margin-top: 16px; background: #0d1421; color: #c8d0dc; border-radius: 18px; padding: 26px 22px; }
    .footer-grid { display: grid; grid-template-columns: 1.3fr repeat(4, 1fr); gap: 20px; }
    .footer-grid h4 { margin: 0 0 10px; color: #fff; }
    .footer-grid a, footer p { display: block; color: #aab4c3; margin: 7px 0; font-size: 13px; line-height: 1.45; }
    .copyright { margin-top: 20px; padding-top: 14px; border-top: 1px solid rgba(255,255,255,.1); color: #8b96a7; }
    @media (max-width: 1100px) { .hero { grid-template-columns: 1fr; } .metrics { grid-template-columns: repeat(2, minmax(150px, 1fr)); } .navlinks { display: none; } .search { width: 220px; } .panel-grid { grid-template-columns: repeat(2, minmax(130px, 1fr)); } .footer-grid { grid-template-columns: repeat(2, 1fr); } }
    @media (max-width: 700px) { .top-strip { padding: 0 14px; } .navbar { padding: 0 14px; gap: 12px; } .actions .search-wrap { display: none; } .page { padding: 12px 10px 28px; } .promo { grid-template-columns: 1fr; } .hero, .metrics, .info-grid, .footer-grid { grid-template-columns: 1fr; } .tabs-row { align-items: flex-start; flex-direction: column; } .index-card { grid-template-columns: 1fr 1fr; } .panel-grid { grid-template-columns: 1fr; } h1 { font-size: 28px; } }
  </style>
</head>
