      {rank:5,name:"BNB",symbol:"BNB",price:632.59,h1:.38,h24:1.89,d7:4.98,cap:85.27e9,vol:1.95e9,supply:"134.78M BNB",network:"BSC",cat:"Top",type:"coin",spark:[30,32,41,48,59,69,78]},
      {rank:6,name:"USD Coin",symbol:"USDC",price:1.00,h1:0.00,h24:.02,d7:.02,cap:54.66e9,vol:12.18e9,supply:"54.65B USDC",network:"Base",cat:"Most Visited",type:"stablecoin",spark:[51,50,51,50,51,50,51]},
      {rank:7,name:"Solana",symbol:"SOL",price:88.25,h1:.67,h24:3.74,d7:5.67,cap:50.77e9,vol:6.71e9,supply:"575.26M SOL",network:"Solana",cat:"Trending",type:"coin",spark:[21,33,42,54,62,70,82]},
