      {rank:8,name:"Dogecoin",symbol:"DOGE",price:.1592,h1:-.14,h24:1.92,d7:8.41,cap:23.79e9,vol:1.91e9,supply:"149.4B DOGE",network:"More",cat:"Most Visited",type:"coin",spark:[18,24,30,48,62,80,87]},
      {rank:9,name:"TRON",symbol:"TRX",price:.2724,h1:.09,h24:-.42,d7:1.19,cap:23.49e9,vol:.83e9,supply:"86.25B TRX",network:"More",cat:"Top",type:"coin",spark:[45,46,44,48,50,52,55]},
      {rank:10,name:"Cardano",symbol:"ADA",price:.5938,h1:-.22,h24:2.18,d7:6.42,cap:21.02e9,vol:.91e9,supply:"35.4B ADA",network:"More",cat:"Watchlist",type:"coin",spark:[23,26,37,44,57,69,81]},
      {rank:11,name:"Chainlink",symbol:"LINK",price:13.48,h1:.31,h24:1.15,d7:3.92,cap:8.89e9,vol:.62e9,supply:"659.1M LINK",network:"Ethereum",cat:"Prediction Markets",type:"defi",spark:[33,31,39,45,49,55,64]},
      {rank:12,name:"Avalanche",symbol:"AVAX",price:19.74,h1:-.28,h24:-1.04,d7:2.31,cap:8.21e9,vol:.44e9,supply:"416.0M AVAX",network:"More",cat:"New",type:"coin",spark:[51,48,45,43,50,56,61]}
    ];
    const generatedNames = ["Toncoin","Shiba Inu","Polkadot","Uniswap","Litecoin","Aptos","Internet Computer","Pepe","Dai","Bittensor","Stellar","Near Protocol","Kaspa","Ethereum Classic","Monero","OKB","Aave","Cronos","Filecoin","Mantle","Arbitrum","VeChain","Cosmos","Render","Optimism","Injective","Sui","Celestia","The Graph","Fantom","Maker","Algorand","Stacks","Bonk","Theta Network","Lido DAO","Jupiter","Sei","Worldcoin","Flow","Gala","Quant","JasmyCoin","Floki","Pyth Network","Helium","Core","Brett","Ethena","Bitget Token","Tezos","EOS","Beam","Neo","Akash Network","dYdX","Notcoin","Kava","Axie Infinity","eCash","Chiliz","Mina","Wormhole","Decentraland","Ronin","ApeCoin","Synthetix","PancakeSwap","Pendle","IOTA","Zcash","Gnosis","Conflux","SAND","Jito","Curve DAO","ORDI","1inch","Raydium","Luna Classic","Osmosis","Nexo","Safe","Blur","SuperVerse","Zilliqa","Celo","Enjin Coin","Amp","IoTeX","Ankr","Terra","Rocket Pool","ZKsync","Arkham","Mog Coin","EigenLayer","Reserve Rights"];
    const networkCycle = ["Ethereum","Solana","Base","BSC","More"];
    const catCycle = ["Top","Trending","Watchlist","Prediction Markets","Most Visited","New"];
    const colorCycle = ["#f7931a","#627eea","#26a17b","#23292f","#f3ba2f","#2775ca","#14f195","#c2a633","#8247e5","#3861fb","#00a3ff","#ef4444"];
    const assets = [...seedAssets];
    generatedNames.forEach((name, i) => {
      const rank = i + 13;
      const symbol = name.split(/\s+/).map(w => w[0]).join("").slice(0,4).toUpperCase();
      const cap = Math.max(380e6, 7.8e9 * Math.pow(.94, i));
      const price = Math.max(.004, (420 / (rank * .82)) * (1 + (i % 7) / 12));
      const h24 = ((i % 9) - 3) * .74 + (i % 2 ? .41 : -.18);
      assets.push({
        rank, name, symbol, price, h1: ((i % 7) - 3) * .17, h24, d7: ((i % 13) - 4) * 1.13,
        cap, vol: cap * (.025 + (i % 8) * .007), supply: `${(cap / price / 1e6).toFixed(2)}M ${symbol}`,
        network: networkCycle[i % networkCycle.length], cat: catCycle[i % catCycle.length], type: i % 11 === 0 ? "defi" : "coin",
        spark: Array.from({length:7}, (_, j) => Math.max(8, Math.min(92, 38 + h24 * 5 + j * ((i % 5) - 1) + Math.sin(i + j) * 14)))
      });
    });
    const state = { network:"All Networks", category:"Top", page:1, sort:"rank", dir:1, search:"", gainers:false, minCap:0, change:"all", type:"all", hidden:new Set() };
    const columns = [
      ["rank", "Rank"], ["name", "Name"], ["price", "Price"], ["change1h", "1h %"], ["change24h", "24h %"], ["change7d", "7d %"], ["marketCap", "Market Cap"], ["volume", "Volume(24h)"], ["supply", "Circulating Supply"], ["spark", "Last 7 Days"]
    ];
    const fmtMoney = value => value >= 1e12 ? `$${(value/1e12).toFixed(2)}T` : value >= 1e9 ? `$${(value/1e9).toFixed(2)}B` : value >= 1e6 ? `$${(value/1e6).toFixed(2)}M` : `$${value.toLocaleString(undefined,{maximumFractionDigits:2})}`;
    const fmtPrice = value => value >= 1000 ? `$${value.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}` : value >= 1 ? `$${value.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}` : `$${value.toFixed(4)}`;
    const pct = value => `<span class="${value >= 0 ? 'up' : 'down'}">${value >= 0 ? '+' : ''}${value.toFixed(2)}%</span>`;
    function sparkline(points, positive) {
      const w = 118, h = 34, min = Math.min(...points), max = Math.max(...points), range = max - min || 1;
      const coords = points.map((p, i) => [i * (w/(points.length-1)), h - ((p-min)/range)*26 - 4]);
      const d = coords.map((p,i) => `${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');
      const fill = `${d} L${w},${h} L0,${h} Z`;
      const color = positive ? '#16c784' : '#ea3943';
      return `<svg class="spark" viewBox="0 0 ${w} ${h}" aria-hidden="true"><path class="spark-fill" d="${fill}" fill="${color}"></path><path d="${d}" stroke="${color}"></path></svg>`;
    }
    function filteredAssets() {
      let list = assets.filter(a => state.network === "All Networks" || a.network === state.network || (state.network === "More" && a.network === "More"));
      if (state.category !== "Top" && state.category !== "More") list = list.filter(a => a.cat === state.category || (state.category === "Watchlist" && a.rank % 5 === 0));
      if (state.gainers) list = list.filter(a => a.h24 > 0);
      if (state.minCap) list = list.filter(a => a.cap >= state.minCap);
      if (state.change === "positive") list = list.filter(a => a.h24 >= 0);
      if (state.change === "negative") list = list.filter(a => a.h24 < 0);
      if (state.type !== "all") list = list.filter(a => a.type === state.type);
      if (state.search) list = list.filter(a => `${a.name} ${a.symbol}`.toLowerCase().includes(state.search));
      if (!list.length) list = assets.slice(0, 100);
      return list.sort((a,b) => {
        const key = state.sort;
        const av = key === 'marketCap' ? a.cap : key === 'volume' ? a.vol : key === 'price' ? a.price : key === 'change1h' ? a.h1 : key === 'change24h' ? a.h24 : key === 'change7d' ? a.d7 : key === 'name' ? a.name : a.rank;
        const bv = key === 'marketCap' ? b.cap : key === 'volume' ? b.vol : key === 'price' ? b.price : key === 'change1h' ? b.h1 : key === 'change24h' ? b.h24 : key === 'change7d' ? b.d7 : key === 'name' ? b.name : b.rank;
        return typeof av === 'string' ? av.localeCompare(bv) * state.dir : (av - bv) * state.dir;
      });
    }
    function renderTabs() {
      document.getElementById('networkTabs').innerHTML = networks.map(n => `<button class="tab ${state.network===n?'active':''}" data-network="${n}">${n}</button>`).join('');
      document.getElementById('categoryTabs').innerHTML = categories.map(c => `<button class="tab ${state.category===c?'active':''}" data-category="${c}">${c}</button>`).join('');
      document.getElementById('activeFilter').textContent = `${state.network} · ${state.category}`;
    }
    function renderColumns() {
      document.getElementById('columnChecks').innerHTML = columns.map(([id,label]) => `<label class="check"><input type="checkbox" data-column-toggle="${id}" ${state.hidden.has(id)?'':'checked'} ${id==='name'?'disabled':''}> ${label}</label>`).join('');
      columns.forEach(([id]) => document.querySelectorAll(`[data-col="${id}"]`).forEach(el => el.classList.toggle('hidden-col', state.hidden.has(id))));
    }
    function rowHtml(asset) {
      const color = colorCycle[(asset.rank - 1) % colorCycle.length];
      return `<tr>
        <td data-col="rank"><span class="watch ${asset.rank % 5 === 0 ? 'active':''}">★</span>${asset.rank}</td>
        <td data-col="name"><div class="coin"><span class="coin-icon" style="background:${color}">${asset.symbol.slice(0,2)}</span><span><span class="coin-name">${asset.name}</span><span class="coin-symbol">${asset.symbol}</span></span></div></td>
        <td data-col="price">${fmtPrice(asset.price)}</td>
        <td data-col="change1h">${pct(asset.h1)}</td>
        <td data-col="change24h">${pct(asset.h24)}</td>
        <td data-col="change7d">${pct(asset.d7)}</td>
        <td data-col="marketCap">${fmtMoney(asset.cap)}</td>
        <td data-col="volume">${fmtMoney(asset.vol)}</td>
        <td data-col="supply">${asset.supply}</td>
        <td data-col="spark">${sparkline(asset.spark, asset.d7 >= 0)}</td>
      </tr>`;
    }
    function renderTable() {
      const list = filteredAssets();
      const pageSize = 100;
      const start = (state.page - 1) * pageSize;
      const pageAssets = Array.from({length: pageSize}, (_, i) => list[(start + i) % list.length]).map((a, i) => ({...a, rank: start + i + 1}));
      document.querySelector('#cryptoTable tbody').innerHTML = pageAssets.map(rowHtml).join('');
      document.getElementById('showingText').textContent = `Showing ${start + 1}–${start + pageSize} of 8,364 assets`;
      document.getElementById('pages').innerHTML = [1,2,3,4].map(p => `<button class="page-btn ${state.page===p?'active':''}" data-page="${p}">${p}</button>`).join('') + `<span>...</span><button class="page-btn" data-page="84">84</button>`;
      renderColumns();
    }
    function renderAll() { renderTabs(); renderTable(); }
    document.addEventListener('click', e => {
      const network = e.target.closest('[data-network]');
      const category = e.target.closest('[data-category]');
      const page = e.target.closest('[data-page]');
      const th = e.target.closest('th[data-sort]');
      const colToggle = e.target.closest('[data-column-toggle]');
      if (network) { state.network = network.dataset.network; state.page = 1; renderAll(); }
      if (category) { state.category = category.dataset.category; state.page = 1; renderAll(); }
      if (page) { state.page = Number(page.dataset.page); renderTable(); }
      if (th) { const sort = th.dataset.sort; state.dir = state.sort === sort ? state.dir * -1 : -1; state.sort = sort; renderTable(); }
      if (colToggle) { colToggle.checked ? state.hidden.delete(colToggle.dataset.columnToggle) : state.hidden.add(colToggle.dataset.columnToggle); renderTable(); }
    });
    document.getElementById('filtersBtn').onclick = () => document.getElementById('filtersPanel').classList.toggle('open');
    document.getElementById('columnsBtn').onclick = () => document.getElementById('columnsPanel').classList.toggle('open');
    document.getElementById('sortMarketCap').onclick = () => { state.sort='marketCap'; state.dir=-1; renderTable(); };
    document.getElementById('sortVolume').onclick = () => { state.sort='volume'; state.dir=-1; renderTable(); };
    document.getElementById('gainFilter').onclick = () => { state.gainers = !state.gainers; document.getElementById('gainFilter').classList.toggle('active', state.gainers); renderTable(); };
    document.getElementById('resetFilters').onclick = () => { Object.assign(state, {network:'All Networks', category:'Top', page:1, sort:'rank', dir:1, search:'', gainers:false, minCap:0, change:'all', type:'all'}); document.getElementById('search').value=''; document.getElementById('quickSearch').value=''; renderAll(); };
    document.getElementById('applyFilters').onclick = () => { state.minCap = Number(document.getElementById('minCap').value); state.change = document.getElementById('changeFilter').value; state.type = document.getElementById('assetType').value; state.search = document.getElementById('quickSearch').value.trim().toLowerCase(); state.page = 1; renderTable(); };
    document.getElementById('search').addEventListener('input', e => { state.search = e.target.value.trim().toLowerCase(); state.page = 1; renderTable(); });
    document.getElementById('readMore').onclick = () => { const more = document.getElementById('moreSummary'); more.classList.toggle('open'); document.getElementById('readMore').textContent = more.classList.contains('open') ? 'Show Less' : 'Read More'; };
    let promoIndex = 0;
    function showPromo(i) { promoIndex = (i + promos.length) % promos.length; document.getElementById('promoText').textContent = promos[promoIndex][0]; document.getElementById('promoSub').textContent = promos[promoIndex][1]; }
    document.getElementById('prevPromo').onclick = () => showPromo(promoIndex - 1);
    document.getElementById('nextPromo').onclick = () => showPromo(promoIndex + 1);
    setInterval(() => showPromo(promoIndex + 1), 5000);
    renderAll();
  </script>
</body>
</html>
EOF
